#!/usr/bin/env node
// Fails when a docs page is in no sidebar. sidebars.js lists most pages by id,
// so a new page outside an autogenerated directory is otherwise published
// with no navigation entry and nothing reports it.
//
// Usage: node scripts/check-sidebar-coverage.mjs

import { createRequire } from "node:module";
import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

const require = createRequire(import.meta.url);
const sidebars = require("../sidebars.js");

// Pages kept out of the sidebar on purpose.
const UNLISTED = new Set(["quick-start"]);

const explicit = new Set();
const autoDirs = [];
const walkItems = (items) => {
  for (const item of items) {
    if (typeof item === "string") {
      explicit.add(item);
    } else if (item.type === "doc" || item.type === "ref") {
      explicit.add(item.id);
    } else if (item.type === "autogenerated") {
      autoDirs.push(item.dirName);
    } else if (item.type === "category") {
      if (item.link?.type === "doc") explicit.add(item.link.id);
      walkItems(item.items);
    }
  }
};
for (const items of Object.values(sidebars)) walkItems(items);

const docsDir = path.resolve("docs");
const ids = [];
const walkDocs = (dir) => {
  for (const entry of readdirSync(dir)) {
    const p = path.join(dir, entry);
    if (statSync(p).isDirectory()) {
      walkDocs(p);
    } else if (/\.mdx?$/.test(entry) && !entry.startsWith("_")) {
      const rel = path.relative(docsDir, p).replace(/\.mdx?$/, "");
      // A frontmatter id replaces the file name in the doc id.
      const fm = readFileSync(p, "utf-8").match(/^---\n([\s\S]*?)\n---/);
      const custom = fm && fm[1].match(/^id:\s*["']?([^"'\n]+)["']?\s*$/m);
      ids.push(custom ? path.posix.join(path.posix.dirname(rel), custom[1].trim()) : rel);
    }
  }
};
walkDocs(docsDir);

const missing = ids.filter(
  (id) =>
    !UNLISTED.has(id) &&
    !explicit.has(id) &&
    !autoDirs.some((dir) => id.startsWith(`${dir}/`)),
);
const stale = [...explicit].filter((id) => !ids.includes(id));

if (missing.length > 0) {
  console.error("pages in no sidebar (add them to sidebars.js):");
  for (const id of missing.sort()) console.error(`  ${id}`);
}
if (stale.length > 0) {
  console.error("sidebars.js lists pages that do not exist:");
  for (const id of stale.sort()) console.error(`  ${id}`);
}
if (missing.length > 0 || stale.length > 0) process.exit(1);
console.log(`${ids.length} pages, all in the sidebar`);
